CREATE TABLE `calendars` (
	`id` text PRIMARY KEY NOT NULL,
	`user_id` text NOT NULL,
	`name` text NOT NULL,
	`color` text,
	`kind` text DEFAULT 'ics' NOT NULL,
	`url` text NOT NULL,
